CREATE view adamtaraz as SELECT     dbo.BEDNES.N_S, dbo.BEDNES.SumOfBED - dbo.BEDNES.SumOfBES AS MAND, dbo.DEED_HED.DATE_S, dbo.DEED_HED.SHARH_S,                      dbo.DEED_HED.NO_S , dbo.DEED_HED.USER_NAME  FROM         dbo.BEDNES INNER JOIN                      dbo.DEED_HED ON dbo.BEDNES.N_S = dbo.DEED_HED.N_S WHERE     (dbo.BEDNES.SumOfBED - dbo.BEDNES.SumOfBES > 0.9) OR                      (dbo.BEDNES.SumOfBED - dbo.BEDNES.SumOfBES < - 0.9)
